return [{ json: stepPrepareFollowUpJob($input.first().json, NICHE_PACKS) }];

// Plan Gmail Searches
// Builds Gmail searches for the addresses you pitched: what you sent, and what they replied.
// Generated by Client Finder Agent. You normally never need to edit this node: change the
// values in the "⚙️ Settings" node instead.

// ---- util.js ----

function str(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function num(v, fallback = null) {
  if (v === '' || v === null || v === undefined || typeof v === 'boolean') return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function int(v, fallback = 0) {
  const n = num(v, null);
  return n === null ? fallback : Math.trunc(n);
}

// ---- places.js ----

// Collects every string inside an error payload. n8n stores API errors in different shapes
// ({message: '403 - "{...}"'}, {error: '{"error":{...}}', statusCode}, {description}), so checks run on all of it.
function errorText(err) {
  const parts = [];
  const walk = (v, depth) => {
    if (v === null || v === undefined || depth > 4) return;
    if (typeof v === 'string') {
      parts.push(v.replace(/\\"/g, '"'));
      return;
    }
    if (typeof v !== 'object') return;
    for (const k of ['message', 'description', 'error', 'status', 'statusText', 'body', 'details']) if (k in v) walk(v[k], depth + 1);
  };
  walk(err, 0);
  return parts.join(' | ');
}

// The most useful single message inside an error payload (the API's own message when present).
function errorSummary(err) {
  const text = errorText(err);
  const m = text.match(/"message"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (m) return m[1];
  const e = err || {};
  return str(typeof e === 'string' ? e : e.message || e.description || text).slice(0, 300);
}

// ---- sheet.js ----

const STATUS = {
  NEW: 'New',
  PITCH_READY: 'Pitch ready',
  DRAFT_READY: 'Draft ready',
  CONTACTED: 'Contacted',
  FOLLOW_UP_DRAFTED: 'Follow-up drafted',
  REPLIED: 'Replied',
  MEETING: 'Meeting booked',
  WON: 'Won',
  LOST: 'Lost',
  DO_NOT_CONTACT: 'Do not contact',
  NOT_INTERESTED: 'Not interested',
  BOUNCED: 'Bounced',
};

// Statuses after which the workflows must never email that address again.
const FINAL_STATUSES = [STATUS.REPLIED, STATUS.MEETING, STATUS.WON, STATUS.LOST, STATUS.DO_NOT_CONTACT, STATUS.NOT_INTERESTED, STATUS.BOUNCED];

// ---- followup.js ----

const EMAIL_RE = /[a-z0-9._%+-]{1,64}@[a-z0-9.-]{1,253}\.[a-z]{2,24}/gi;

function emailsIn(header) {
  return (str(header).match(EMAIL_RE) || []).map((e) => e.toLowerCase());
}

function isFinalStatus(status) {
  const s = str(status).toLowerCase();
  return FINAL_STATUSES.some((f) => f.toLowerCase() === s);
}

// Addresses that must never be emailed again because some row with that address has a final status
// (Replied, Do not contact, Bounced...), even if another row (another listing of the same business) does not.
function suppressedEmails(rows) {
  const out = new Set();
  for (const r of rows || []) if (r && isFinalStatus(r.Status)) for (const e of emailsIn(r.Email)) out.add(e);
  return out;
}

// Rows that may need a follow-up: an address, a Place ID, not final, and pitched (by the workflow or by hand).
function candidateRows(rows) {
  const suppressed = suppressedEmails(rows);
  return (rows || []).filter((r) => {
    const email = emailsIn(r && r.Email)[0];
    if (!email || !str(r['Place ID']) || isFinalStatus(r.Status) || suppressed.has(email)) return false;
    const pitched = str(r['Email Subject']) || str(r['Last Contacted']) || [STATUS.CONTACTED, STATUS.FOLLOW_UP_DRAFTED, STATUS.DRAFT_READY, STATUS.PITCH_READY].includes(str(r.Status));
    return Boolean(pitched);
  });
}

// One Gmail search per chunk of addresses, for sent mail and for replies (in:anywhere also finds archived,
// trashed and spam replies: a reply is a reply even if it was deleted).
function buildGmailQueries(rows, options) {
  const opts = options || {};
  const lookbackDays = int(opts.lookbackDays, 120) || 120;
  const chunkSize = int(opts.chunkSize, 25) || 25;
  const emails = [...new Set(candidateRows(rows).map((r) => emailsIn(r.Email)[0]))];
  const queries = [];
  for (let i = 0; i < emails.length; i += chunkSize) {
    const chunk = emails.slice(i, i + chunkSize);
    queries.push({ kind: 'sent', q: `in:sent newer_than:${lookbackDays}d {${chunk.map((e) => `to:${e}`).join(' ')}}` });
    queries.push({ kind: 'reply', q: `in:anywhere -in:sent -in:drafts newer_than:${lookbackDays}d {${chunk.map((e) => `from:${e}`).join(' ')}}` });
  }
  return queries;
}

// ---- steps.js ----

function stop(title, message, fatal) {
  return { stop: true, fatal: Boolean(fatal), title, message };
}

function isSheetUrl(url) {
  return /^https:\/\/docs\.google\.com\/spreadsheets\/d\/[a-zA-Z0-9_-]{20,}/.test(str(url));
}

// n8n's Google Sheets node with "continue on error" does not output rows when it fails: it outputs its first input
// item (a lead or the job) with an `error` property next to `json`. Turns the node's items into rows or { error }.
function sheetRowsFrom(items) {
  return (items || []).map((item) => {
    const it = item || {};
    const json = it.json || {};
    if (it.error !== undefined && it.error !== null) return { error: Object.keys(it.error).length ? it.error : { message: 'Google Sheets request failed' } };
    if (json.error !== undefined) return { error: json.error };
    if (json['Place ID'] === undefined && (json.placeId !== undefined || json.settings !== undefined || json.search !== undefined)) {
      return { error: { message: 'Google Sheets request failed' } };
    }
    return json;
  });
}

function sheetHint(msg) {
  if (/not found|404|Unable to parse range|Leads/i.test(msg)) {
    return 'n8n could not find the "Leads" tab. Import the Client Finder CRM template into Google Sheets (it already has the tab and columns) and paste that sheet\'s URL into Settings.';
  }
  return 'Check that googleSheetUrl in Settings is correct, the sheet has a tab named "Leads", and the Google Sheets credential belongs to the Google account that owns the sheet.';
}

function stepPlanGmailSearches(rows, settings) {
  const valid = (rows || []).filter((r) => r && Object.keys(r).length);
  const sheetError = valid.find((r) => r.error);
  if (sheetError) {
    const msg = errorSummary(sheetError.error) || 'Google Sheets request failed';
    return [stop("Couldn't read your Google Sheet", `${msg.slice(0, 200)} — ${sheetHint(`${msg} ${errorText(sheetError.error)}`)}`, true)];
  }
  if (!isSheetUrl(settings && settings.googleSheetUrl)) return [stop('Settings needed', 'Paste your Client Finder Google Sheet URL into googleSheetUrl in the "⚙️ Settings" node.', true)];
  const queries = buildGmailQueries(valid);
  if (!queries.length) return [stop('Nothing to follow up', 'No leads with an email address are waiting for a reply.')];
  return queries;
}

// ---- this step ----
const job = $('Prepare Follow-ups').first().json;
const rows = sheetRowsFrom($input.all());
return stepPlanGmailSearches(rows, job.settings).map((json) => ({ json }));

// Plan Thread Checks
// Lists the Gmail threads your pitches were sent in, to catch replies from any address and bounces.
// Generated by Client Finder Agent. You normally never need to edit this node: change the
// values in the "⚙️ Settings" node instead.

// ---- util.js ----

function str(v) {
  return v === undefined || v === null ? '' : String(v).trim();
}

function num(v, fallback = null) {
  if (v === '' || v === null || v === undefined || typeof v === 'boolean') return fallback;
  const n = Number(v);
  return Number.isFinite(n) ? n : fallback;
}

function int(v, fallback = 0) {
  const n = num(v, null);
  return n === null ? fallback : Math.trunc(n);
}

function utcDate(y, m, d) {
  const dt = new Date(Date.UTC(y, m - 1, d));
  // Date.UTC silently rolls 25/09 into the 9th month of the next year: reject impossible dates instead.
  return dt.getUTCFullYear() === y && dt.getUTCMonth() === m - 1 && dt.getUTCDate() === d ? dt : null;
}

// Parses dates written by people or by Google Sheets ("2026-10-06", "10/6/2026", "25/09/2026", "06.10.2026",
// a Sheets serial day number, "2026-10-06T09:00:00Z"). Slashed dates are month-first unless the first number is
// over 12 or options.dayFirst is set; dotted dates (06.10.2026) are day-first. Impossible dates return null.
function parseDate(value, options) {
  if (value instanceof Date) return Number.isNaN(value.getTime()) ? null : value;
  if (typeof value === 'number' && Number.isFinite(value)) {
    // Google Sheets serial day number (days since 1899-12-30) or epoch milliseconds.
    if (value > 20000 && value < 80000) return new Date(Math.round((value - 25569) * 86400000));
    if (value > 1e11) return new Date(value);
    return null;
  }
  const s = str(value);
  if (!s) return null;
  const iso = s.match(/^(\d{4})-(\d{2})-(\d{2})$/);
  if (iso) return utcDate(Number(iso[1]), Number(iso[2]), Number(iso[3]));
  const parts = s.match(/^(\d{1,2})([/.])(\d{1,2})\2(\d{4})$/);
  if (parts) {
    const a = Number(parts[1]);
    const b = Number(parts[3]);
    const y = Number(parts[4]);
    const dayFirst = a > 12 || (b <= 12 && (parts[2] === '.' || Boolean(options && options.dayFirst)));
    return dayFirst ? utcDate(y, b, a) : utcDate(y, a, b);
  }
  if (/^\d+(\.\d+)?$/.test(s)) return parseDate(Number(s));
  if (/^\d{1,2}[/.]\d{1,2}[/.]\d{2,4}$/.test(s)) return null; // other numeric forms are too ambiguous to guess
  const d = new Date(s);
  return Number.isNaN(d.getTime()) ? null : d;
}

// ---- places.js ----

// Collects every string inside an error payload. n8n stores API errors in different shapes
// ({message: '403 - "{...}"'}, {error: '{"error":{...}}', statusCode}, {description}), so checks run on all of it.
function errorText(err) {
  const parts = [];
  const walk = (v, depth) => {
    if (v === null || v === undefined || depth > 4) return;
    if (typeof v === 'string') {
      parts.push(v.replace(/\\"/g, '"'));
      return;
    }
    if (typeof v !== 'object') return;
    for (const k of ['message', 'description', 'error', 'status', 'statusText', 'body', 'details']) if (k in v) walk(v[k], depth + 1);
  };
  walk(err, 0);
  return parts.join(' | ');
}

// The most useful single message inside an error payload (the API's own message when present).
function errorSummary(err) {
  const text = errorText(err);
  const m = text.match(/"message"\s*:\s*"((?:[^"\\]|\\.)*)"/);
  if (m) return m[1];
  const e = err || {};
  return str(typeof e === 'string' ? e : e.message || e.description || text).slice(0, 300);
}

// ---- sheet.js ----

const STATUS = {
  NEW: 'New',
  PITCH_READY: 'Pitch ready',
  DRAFT_READY: 'Draft ready',
  CONTACTED: 'Contacted',
  FOLLOW_UP_DRAFTED: 'Follow-up drafted',
  REPLIED: 'Replied',
  MEETING: 'Meeting booked',
  WON: 'Won',
  LOST: 'Lost',
  DO_NOT_CONTACT: 'Do not contact',
  NOT_INTERESTED: 'Not interested',
  BOUNCED: 'Bounced',
};

// Statuses after which the workflows must never email that address again.
const FINAL_STATUSES = [STATUS.REPLIED, STATUS.MEETING, STATUS.WON, STATUS.LOST, STATUS.DO_NOT_CONTACT, STATUS.NOT_INTERESTED, STATUS.BOUNCED];

// ---- followup.js ----

const EMAIL_RE = /[a-z0-9._%+-]{1,64}@[a-z0-9.-]{1,253}\.[a-z]{2,24}/gi;

const BOUNCE_FROM = /mailer-daemon|postmaster@|mail delivery (subsystem|system)/i;

const BOUNCE_SUBJECT = /delivery status notification|undeliverable|undelivered mail|mail delivery failed|delivery failure|returned mail|failure notice|address not found|delivery has failed/i;

const AUTO_REPLY_SUBJECT = /^\s*(automatic reply|auto[- ]?reply|autoreply|out of (the )?office|abwesenheit|réponse automatique|respuesta automática|risposta automatica|afwezig)/i;

function emailsIn(header) {
  return (str(header).match(EMAIL_RE) || []).map((e) => e.toLowerCase());
}

function isFinalStatus(status) {
  const s = str(status).toLowerCase();
  return FINAL_STATUSES.some((f) => f.toLowerCase() === s);
}

// Addresses that must never be emailed again because some row with that address has a final status
// (Replied, Do not contact, Bounced...), even if another row (another listing of the same business) does not.
function suppressedEmails(rows) {
  const out = new Set();
  for (const r of rows || []) if (r && isFinalStatus(r.Status)) for (const e of emailsIn(r.Email)) out.add(e);
  return out;
}

// Rows that may need a follow-up: an address, a Place ID, not final, and pitched (by the workflow or by hand).
function candidateRows(rows) {
  const suppressed = suppressedEmails(rows);
  return (rows || []).filter((r) => {
    const email = emailsIn(r && r.Email)[0];
    if (!email || !str(r['Place ID']) || isFinalStatus(r.Status) || suppressed.has(email)) return false;
    const pitched = str(r['Email Subject']) || str(r['Last Contacted']) || [STATUS.CONTACTED, STATUS.FOLLOW_UP_DRAFTED, STATUS.DRAFT_READY, STATUS.PITCH_READY].includes(str(r.Status));
    return Boolean(pitched);
  });
}

function messageTime(m) {
  const ms = int(m && m.internalDate, 0);
  if (ms > 0) return new Date(ms);
  return parseDate(m && (m.date || m.Date));
}

function hasLabel(m, label) {
  const labels = (m && (m.labels || m.labelIds)) || [];
  return labels.some((l) => (typeof l === 'string' ? l : l && (l.id || l.name)) === label);
}

function isSentMessage(m) {
  return hasLabel(m, 'SENT');
}

function track(map, key, t, extra) {
  const r = map[key] || (map[key] = Object.assign({ first: t, last: t }, extra || {}));
  if (t < r.first) r.first = t;
  if (t > r.last) r.last = t;
  return r;
}

// messages = simplified Gmail messages (From, To, Cc, Subject, internalDate, labels, threadId) from the searches.
// threadMessages = every message of the threads the pitches were sent in (any sender: a colleague's reply or a bounce).
function indexGmail(messages, leadEmails, threadMessages) {
  const wanted = new Set((leadEmails || []).map((e) => e.toLowerCase()));
  const sent = {};
  const replies = {};
  const bounces = {};
  for (const m of messages || []) {
    if (!m || m.error) continue;
    const t = messageTime(m);
    if (!t) continue;
    const from = emailsIn(m.From)[0] || '';
    if (wanted.has(from) && !isSentMessage(m) && !hasLabel(m, 'DRAFT')) {
      if (!AUTO_REPLY_SUBJECT.test(str(m.Subject))) track(replies, from, t, { from });
      continue;
    }
    if (isSentMessage(m)) {
      for (const to of [...emailsIn(m.To), ...emailsIn(m.Cc)]) {
        if (!wanted.has(to)) continue;
        const s = track(sent, to, t, { threadId: str(m.threadId), threads: [] });
        if (t >= s.last) s.threadId = str(m.threadId) || s.threadId;
        if (m.threadId && !s.threads.includes(str(m.threadId))) s.threads.push(str(m.threadId));
      }
    }
  }
  // Thread check: any incoming message in a thread we sent to a lead counts, whoever wrote it.
  const threadLead = {};
  for (const [email, s] of Object.entries(sent)) for (const id of s.threads) threadLead[id] = email;
  for (const m of threadMessages || []) {
    if (!m || m.error || !m.threadId) continue;
    const email = threadLead[str(m.threadId)];
    if (!email || isSentMessage(m) || hasLabel(m, 'DRAFT')) continue;
    const t = messageTime(m);
    if (!t || t < sent[email].first) continue;
    const from = emailsIn(m.From)[0] || str(m.From);
    if (BOUNCE_FROM.test(str(m.From)) || BOUNCE_SUBJECT.test(str(m.Subject))) track(bounces, email, t);
    else if (!AUTO_REPLY_SUBJECT.test(str(m.Subject))) track(replies, email, t, { from });
  }
  return { sent, replies, bounces };
}

// The thread IDs to read for the thread check (every thread a pitch or follow-up was sent in).
function threadsToCheck(index) {
  const ids = new Set();
  for (const s of Object.values((index && index.sent) || {})) for (const id of s.threads || []) if (id) ids.add(id);
  return [...ids];
}

// ---- steps.js ----

function stop(title, message, fatal) {
  return { stop: true, fatal: Boolean(fatal), title, message };
}

// n8n's Google Sheets node with "continue on error" does not output rows when it fails: it outputs its first input
// item (a lead or the job) with an `error` property next to `json`. Turns the node's items into rows or { error }.
function sheetRowsFrom(items) {
  return (items || []).map((item) => {
    const it = item || {};
    const json = it.json || {};
    if (it.error !== undefined && it.error !== null) return { error: Object.keys(it.error).length ? it.error : { message: 'Google Sheets request failed' } };
    if (json.error !== undefined) return { error: json.error };
    if (json['Place ID'] === undefined && (json.placeId !== undefined || json.settings !== undefined || json.search !== undefined)) {
      return { error: { message: 'Google Sheets request failed' } };
    }
    return json;
